ST.xhtml:p:
RTrigger1Open(CLK := bCylinder1Open OR g_bTurnCylinder1Open);
RTrigger2Open(CLK := bCylinder2Open OR g_bTurnCylinder2Open);
RTrigger3Open(CLK := bCylinder3Open OR g_bTurnCylinder3Open);
RTrigger4Open(CLK := bCylinder4Open OR g_bTurnCylinder4Open);
RTrigger5Open(CLK := bCylinder5Open OR g_bTurnCylinder5Open);

RTrigger1Close(CLK := bCylinder1Close OR g_bTurnCylinder1Close);
RTrigger2Close(CLK := bCylinder2Close OR g_bTurnCylinder2Close);
RTrigger3Close(CLK := bCylinder3Close OR g_bTurnCylinder3Close);
RTrigger4Close(CLK := bCylinder4Close OR g_bTurnCylinder4Close);
RTrigger5Close(CLK := bCylinder5Close OR g_bTurnCylinder5Close);

IF RTrigger1Open.Q THEN
  bCylinder1Open:= FALSE;
  bCylinder1Close:= FALSE;(*资源回收*)
  InPlaceAlarmDelay1(IN :=FALSE);
  g_bTurnCylinder1Open:= FALSE;
  g_bTurnCylinder1Close := FALSE;
  g_bTurnCyl1DownSignalInplaceTimeoutAlarm:= FALSE;
  IF NOT g_bClaw3CylForbid THEN
    g_boTurnCyl01Up := TRUE;
    g_boTurnCyl01Down := FALSE;
    bTurn1DelayFlag := TRUE;
  END_IF;
END_IF;
IF RTrigger1Close.Q THEN
  bCylinder1Open:= FALSE;
  bCylinder1Close:= FALSE;(*资源回收*)
  InPlaceAlarmDelay1(IN :=FALSE);
  g_bTurnCylinder1Open:= FALSE;
  g_bTurnCylinder1Close := FALSE;
  bTurnCyl1UpSignalInplaceTimeoutAlarm:= FALSE;
  g_boTurnCyl01Up := FALSE;
  g_boTurnCyl01Down := TRUE;
  bTurn1DelayFlag := TRUE;
END_IF;
(*hmi状态灯显示,自动下料机中也可使用*)
IF bTurn1UpInPlaceSignal AND g_boTurnCyl01Up THEN(*使用到位信号*)
  IF g_bTurnCyl01UpInPlace AND g_bTurnCyl02UpInPlace AND g_bTurnCyl03UpInPlace AND g_bTurnCyl04UpInPlace THEN
    g_bTurnState1:= TRUE;
    InPlaceAlarmDelay1(IN :=FALSE);
    bTurnCyl1UpSignalInplaceTimeoutAlarm:= FALSE;
  ELSE
    IF NOT g_bTurnState1 THEN
      InPlaceAlarmDelay1(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTurn1UpInPlaceDelay)));
      IF InPlaceAlarmDelay1.Q THEN
        InPlaceAlarmDelay1(IN :=FALSE);
        bTurnCyl1UpSignalInplaceTimeoutAlarm:= TRUE;
      END_IF; 
    END_IF;  
  END_IF;
  IF NOT g_CylAllStateUpDate.BoolArr[23] AND g_bTurnState1 THEN
    bTurnCyl1UpSignalInplaceTimeoutAlarm:=TRUE;
  ELSIF g_CylAllStateUpDate.BoolArr[23] AND g_bTurnState1 THEN
    bTurnCyl1UpSignalInplaceTimeoutAlarm:= FALSE;
  END_IF;
ELSIF bTurn1DownInPlaceSignal AND g_boTurnCyl01Down THEN
  IF g_bTurnCyl01DownInPlace AND g_bTurnCyl02DownInPlace AND g_bTurnCyl03DownInPlace AND g_bTurnCyl04DownInPlace THEN
    g_bTurnState1:= FALSE;
    InPlaceAlarmDelay1(IN :=FALSE);
    g_bTurnCyl1DownSignalInplaceTimeoutAlarm:= FALSE;
  ELSE
    (*到位报警判断使用延时 保证报警时间大于滤波时间*)
    IF g_bTurnState1 THEN
      InPlaceAlarmDelay1(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTurn1DownInPlaceDelay)));
      IF InPlaceAlarmDelay1.Q THEN
        InPlaceAlarmDelay1(IN :=FALSE);
        g_bTurnCyl1DownSignalInplaceTimeoutAlarm:= TRUE;
      END_IF; 
    END_IF;

  END_IF; 
  IF NOT g_CylAllStateUpDate.BoolArr[22] AND NOT g_bTurnState1 THEN
    g_bTurnCyl1DownSignalInplaceTimeoutAlarm:=TRUE;
  ELSIF g_CylAllStateUpDate.BoolArr[22] AND NOT g_bTurnState1 THEN
    g_bTurnCyl1DownSignalInplaceTimeoutAlarm:= FALSE;
  END_IF;
ELSE(*使用延时信号*)
  bTurnCyl1UpSignalInplaceTimeoutAlarm:= FALSE;
  g_bTurnCyl1DownSignalInplaceTimeoutAlarm:= FALSE;
  IF bTurn1DelayFlag THEN
    IF g_boTurnCyl01Up THEN
      InPlaceDelay0(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTurn1UpInPlaceDelay)));
    ELSE
      InPlaceDelay0(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTurn1DownInPlaceDelay)));
    END_IF;
    IF InPlaceDelay0.Q THEN
      bTurn1DelayFlag := FALSE;
      InPlaceDelay0(IN :=FALSE);
      IF g_boTurnCyl01Up AND g_boTurnCyl01Down=FALSE THEN
        g_bTurnState1:= TRUE;
      END_IF;
      IF g_boTurnCyl01Down AND g_boTurnCyl01Up=FALSE THEN
        g_bTurnState1:= FALSE;
      END_IF;
    END_IF;
  END_IF;
END_IF;

