  ELSE
    (*到位报警判断使用延时 保证报警时间大于滤波时间*)
    IF g_bTurnState2 THEN 
      InPlaceAlarmDelay2(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTurn2DownInPlaceDelay)));
      IF InPlaceAlarmDelay2.Q THEN
