  g_bTurnCyl2DownSignalInplaceTimeoutAlarm:= FALSE;
  IF bTurn2DelayFlag THEN
    IF g_boTurnCyl11Up THEN
      InPlaceDelay1(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTurn2UpInPlaceDelay)));
    ELSE
      InPlaceDelay1(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTurn2DownInPlaceDelay)));
    END_IF;
    IF InPlaceDelay1.Q THEN
      bTurn2DelayFlag := FALSE;
      InPlaceDelay1(IN :=FALSE);
      IF g_boTurnCyl11Up AND g_boTurnCyl11Down=FALSE THEN
        g_bTurnState2:= TRUE;
      END_IF;
      IF g_boTurnCyl11Down AND g_boTurnCyl11Up=FALSE THEN
