(*打开输出口控制 气缸使用延时的状态切换  46-54 零件托举气缸的状态切换*)
IF ArrayConfigOutputNumber[46] AND NOT bTurn1UpInPlaceSignal THEN
  g_bTurnState1:= TRUE;
  ArrayConfigOutputNumber[46] := FALSE;
END_IF; 
